def get_short_defaults():
    """Parse short template to get defaults dict: name -> raw value string (with continuations joined?)"""
    txt = T("doxy_short.txt")
    # Short template has lines like "NAME = value" with continuations " \\" + newline + spaces
    # We can parse similarly to config parsing but without warnings, just extract.
    defaults = {}
    lines = txt.splitlines()
    # Join continuations: lines ending with \
    logical = []
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if stripped == "" or stripped.startswith("#"):
            i += 1
            continue
        # Check for continuation
        acc = line
        while acc.rstrip().endswith("\\") and (i+1) < len(lines):
            nxt = lines[i+1]
            # Remove \ and join
            acc = acc.rstrip()[:-1] + " " + nxt.strip()
            i += 1
        logical.append(acc)
        i += 1
    for line in logical:
        if "=" not in line:
            continue
        # split on first =
        # Handle +=? In template, no +=, only =.
        parts = line.split("=", 1)
        name = parts[0].strip()
        val = parts[1].strip()
        defaults[name] = val
    return defaults

def get_list_opts_set():
    """Determine list opts from typeprobe.json"""
    try:
        import json
        txt = T("typeprobe.json")
        data = json.loads(txt)
        s = set()
        for k, v in data.items():
            if "\\" in v:
                s.add(k)
        return s
    except:
        return set()

def get_single_opts_set():
    try:
        import json
        txt = T("typeprobe.json")
        data = json.loads(txt)
        s = set()
        for k, v in data.items():
            if '"a b"' in v:
                s.add(k)
        return s
    except:
        return set()

def parse_short_template_order():
    """Get order of opts as they appear in short template"""
    txt = T("doxy_short.txt")
