# ---------- Helper for file I/O ----------

def ensure_parent_dir(path):
    d = os.path.dirname(path)
    if d and not os.path.exists(d):
        # For -g etc., if parent doesn't exist, error (don't create)
        return False
    return True

def do_g short_flag, config_arg, prog):
    # config_arg is None (use default Doxyfile) or "-" (stdout) or filename
    # short_flag: True for short (no comments)
    content = T("doxy_short.txt") if short_flag else T("doxy_full.txt")
    if config_arg is None:
        config_arg = "Doxyfile"
    if config_arg == "-":
        sys.stdout.write(content)
        return 0
    else:
        # try to write file
        # check parent dir?
        parent = os.path.dirname(config_arg)
        if parent and not os.path.exists(parent):
            sys.stderr.write(f"error: Cannot open file {config_arg} for writing\n")
            return 1
        # if path is dir?
        if os.path.isdir(config_arg):
            sys.stderr.write(f"error: Cannot open file {config_arg} for writing\n")
            return 1
        # backup if exists
        if os.path.exists(config_arg):
            try:
                shutil.copyfile(config_arg, config_arg + ".bak")
            except:
                pass
        try:
            with open(config_arg, "w", encoding="utf-8", newline="\n") as f:
                f.write(content)
        except Exception as e:
            sys.stderr.write(f"error: Cannot open file {config_arg} for writing\n")
            return 1
        # message to stdout
        if config_arg == "Doxyfile":
            sys.stdout.write("\n\nConfiguration file 'Doxyfile' created.\n\nNow edit the configuration file and enter\n\n  doxygen\n\nto generate the documentation for your project\n\n")
        else:
            sys.stdout.write(f"\n\nConfiguration file '{config_arg}' created.\n\nNow edit the configuration file and enter\n\n  doxygen {config_arg}\n\nto generate the documentation for your project\n\n")
        return 0

